static bool find_word(uint16_t start,
                      uint16_t count,
                      uint8_t const* buffer,
                      uint16_t address,
                      uint16_t* value)
{
    uint16_t i;
    uint16_t current;

    for ( i = 0U; i < count; ++i ) {
        current = (uint16_t)(start + i);
        if ( current == address ) {
            *value = modbus_app_regs_get_u16(&buffer[2U * i]);
            return true;
        }
    }
    return false;
}

static int32_t gather_s32(uint16_t start,
                          uint16_t count,
                          uint8_t const* buffer,
                          uint16_t high_address,
                          int32_t current)
{
    uint16_t high;
    uint16_t low;
    bool has_high;
    bool has_low;

    has_high = find_word(start, count, buffer, high_address, &high);
    has_low  = find_word(start, count, buffer, (uint16_t)(high_address + 1U), &low);

    if ( has_high && has_low ) {
        return (int32_t)(((uint32_t)high << 16U) | (uint32_t)low);
    }
    if ( has_high ) {
        return (int32_t)(((uint32_t)high << 16U) | ((uint32_t)current & 0xFFFFU));
    }
    if ( has_low ) {
        return (int32_t)(((uint32_t)current & 0xFFFF0000U) | (uint32_t)low);
    }
    return current;
}

static modbus_slave_exception_t validate_user_write(modbus_app* me,
                                                    uint16_t start,
                                                    uint16_t count,
                                                    uint8_t const* buffer)
{
    param_ch_record_t record;
    uint16_t i;
    uint16_t address;
    uint16_t value;
    uint8_t channel;
    uint8_t offset;

    for ( i = 0U; i < count; ++i ) {
        address = (uint16_t)(start + i);
        value   = modbus_app_regs_get_u16(&buffer[2U * i]);

        if ( address == MODBUS_REG_ADDRESS ) {
            if ( value < 1U || value > 247U ) {
                return MODBUS_SLAVE_EX_ILLEGAL_DATA_VALUE;
            }
        } else if ( address <= MODBUS_REG_USER_LAST ) {
            return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
        } else if ( modbus_app_regs_channel_addr(address, &channel, &offset) ) {
            if ( offset >= MODBUS_REG_CH_RESERVED ) {
                return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
            }
            if ( param_app_get_channel(channel, &record) == false ) {
                return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
            }
            if ( offset == MODBUS_REG_CH_TYPE
                 && modbus_app_regs_type_valid(value) == false ) {
                return MODBUS_SLAVE_EX_ILLEGAL_DATA_VALUE;
            }
            if ( offset == MODBUS_REG_CH_RATE
                 && modbus_app_regs_rate_valid(value) == false ) {
                return MODBUS_SLAVE_EX_ILLEGAL_DATA_VALUE;
            }
            if ( (offset == MODBUS_REG_CH_USER_OFFSET
                  || offset == MODBUS_REG_CH_USER_OFFSET + 1U)
                 && modbus_app_regs_offset_valid(gather_s32(
                        start, count, buffer, MODBUS_REG_CH_USER_OFFSET,
                        record.user_offset))
                        == false ) {
                return MODBUS_SLAVE_EX_ILLEGAL_DATA_VALUE;
            }
            if ( (offset == MODBUS_REG_CH_USER_GAIN
                  || offset == MODBUS_REG_CH_USER_GAIN + 1U)
                 && modbus_app_regs_gain_valid(gather_s32(
                        start, count, buffer, MODBUS_REG_CH_USER_GAIN,
                        record.user_gain))
                        == false ) {
                return MODBUS_SLAVE_EX_ILLEGAL_DATA_VALUE;
            }
        } else {
            return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
        }
    }
    return MODBUS_SLAVE_EX_NONE;
}

static void commit_user_write(modbus_app* me,
                              uint16_t start,
                              uint16_t count,
                              uint8_t const* buffer)
{
    param_sys_record_t sys;
    param_ch_record_t record;
    uint16_t i;
    uint16_t address;
    uint16_t value;
    uint8_t channel;
    uint8_t offset;
    bool sys_changed = false;
    bool ch_changed[MODBUS_REG_CH_COUNT] = {false};
    bool any_changed = false;
    bool linear_ok;

    param_app_get_sys(&sys);

    for ( i = 0U; i < count; ++i ) {
        address = (uint16_t)(start + i);
        value   = modbus_app_regs_get_u16(&buffer[2U * i]);

        if ( address == MODBUS_REG_ADDRESS ) {
            sys.address = value;
            sys_changed = true;
        } else if ( modbus_app_regs_channel_addr(address, &channel, &offset) ) {
            if ( param_app_get_channel(channel, &record) == false ) {
                continue;
            }
            ch_changed[channel] = true;
            any_changed         = true;

            switch ( offset ) {
                case MODBUS_REG_CH_TYPE:
                    record.type = (uint8_t)value;
                    break;
                case MODBUS_REG_CH_RATE:
                    record.rate_index = (uint8_t)value;
                    break;
                case MODBUS_REG_CH_LINEAR_MIN:
                case MODBUS_REG_CH_LINEAR_MIN + 1U:
                    record.linear_min = gather_s32(
                        start, count, buffer, MODBUS_REG_CH_LINEAR_MIN,
                        record.linear_min);
                    break;
                case MODBUS_REG_CH_LINEAR_MAX:
                case MODBUS_REG_CH_LINEAR_MAX + 1U:
                    record.linear_max = gather_s32(
                        start, count, buffer, MODBUS_REG_CH_LINEAR_MAX,
                        record.linear_max);
                    break;
                case MODBUS_REG_CH_USER_OFFSET:
                case MODBUS_REG_CH_USER_OFFSET + 1U:
                    record.user_offset = gather_s32(
                        start, count, buffer, MODBUS_REG_CH_USER_OFFSET,
                        record.user_offset);
                    break;
                case MODBUS_REG_CH_USER_GAIN:
                case MODBUS_REG_CH_USER_GAIN + 1U:
                    record.user_gain = gather_s32(
                        start, count, buffer, MODBUS_REG_CH_USER_GAIN,
                        record.user_gain);
                    break;
                default:
                    break;
            }
            (void)param_app_set_channel(channel, &record);
        }
    }

    if ( sys_changed ) {
        (void)param_app_set_sys(&sys);
        if ( me->slave != NULL ) {
            me->slave->identity.slave_id = (uint8_t)sys.address;
        }
    }

    if ( any_changed ) {
        for ( channel = 0U; channel < MODBUS_REG_CH_COUNT; ++channel ) {
            if ( ch_changed[channel] == false ) {
                continue;
            }
            if ( param_app_get_channel(channel, &record) ) {
                linear_ok = param_app_linear_valid(record.linear_min,
                                                   record.linear_max);
                if ( linear_ok == false ) {
                    me->image.ch[channel].status = 6U;
                    me->image.ch[channel].value  = MODBUS_IMAGE_INVALID_VALUE;
                } else if ( me->image.ch[channel].status == 6U ) {
                    me->image.ch[channel].status = 0U;
                    me->image.ch[channel].value  = MODBUS_IMAGE_INVALID_VALUE;
                }
            }
            notify_channel_config(me, channel);
        }
    }

    if ( sys_changed || any_changed ) {
        note_param_change(me);
    }
}

static modbus_slave_exception_t handle_hidden_write(modbus_app* me,
                                                    uint16_t start,
                                                    uint16_t count,
                                                    uint8_t const* buffer)
{
    uint16_t i;
    uint16_t address;
    uint16_t value;
    uint32_t now;

    if ( modbus_cal_regs_in_block(start, count) == false ) {
        return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
    }
    if ( me->calUnlocked == 0U && range_only_magic(start, count) == false ) {
        return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
    }
    if ( count != 1U && start <= MODBUS_CAL_CMD
         && (uint32_t)start + (uint32_t)count - 1U >= MODBUS_CAL_CMD ) {
        return MODBUS_SLAVE_EX_ILLEGAL_DATA_VALUE;
    }

    for ( i = 0U; i < count; ++i ) {
        address = (uint16_t)(start + i);
        value   = modbus_app_regs_get_u16(&buffer[2U * i]);
        now     = board_tick_get();

        switch ( address ) {
            case MODBUS_CAL_MAGIC1:
                if ( value == MODBUS_CAL_MAGIC1_VALUE ) {
                    me->calMagicStep = 1U;
                    me->calMagicTick = now;
                } else {
                    me->calMagicStep = 0U;
                }
                break;

            case MODBUS_CAL_MAGIC2:
                if ( me->calMagicStep == 1U
                     && (uint32_t)(now - me->calMagicTick)
                            <= MODBUS_CAL_MAGIC_WINDOW_MS
                     && value == MODBUS_CAL_MAGIC2_VALUE ) {
                    me->calUnlocked  = 1U;
                    me->calMagicStep = 0U;
                    me->calChannel   = 0xFFU;
                    me->calType      = 0xFFU;
                    rearm_hidden_timeout(me);
                    dispatch_cal(me, &cal_enter_evt);
                } else {
                    me->calMagicStep = 0U;
                }
                break;

            case MODBUS_CAL_CHANNEL:
                me->calChannel = (value < CAL_DATA_CHANNEL_COUNT)
                                     ? (uint8_t)value
                                     : 0xFFU;
                break;

            case MODBUS_CAL_TYPE:
                me->calType = (value < CAL_DATA_TYPE_COUNT) ? (uint8_t)value
                                                            : 0xFFU;
                break;

            case MODBUS_CAL_CMD:
                if ( modbus_cal_regs_valid_cmd(value) == false ) {
                    return MODBUS_SLAVE_EX_ILLEGAL_DATA_VALUE;
                } else if ( value == MODBUS_CAL_CMD_EXIT ) {
                    lock_hidden(me);
                    dispatch_cal(me, &cal_exit_evt);
                } else {
                    if ( value == MODBUS_CAL_CMD_SELECT ) {
                        cal_select_evt_t evt;

                        evt.super.sig = CAL_SELECT_SIG;
                        evt.channel   = me->calChannel;
                        evt.type      = me->calType;
                        dispatch_cal(me, &evt.super);
                    } else if ( value == MODBUS_CAL_CMD_LOW ) {
                        dispatch_cal(me, &cal_low_evt);
                    } else if ( value == MODBUS_CAL_CMD_HIGH ) {
                        dispatch_cal(me, &cal_high_evt);
                    } else if ( value == MODBUS_CAL_CMD_COMMIT ) {
                        dispatch_cal(me, &cal_commit_evt);
                    } else {
                        dispatch_cal(me, &cal_abort_evt);
                    }
                }
                break;

            default:
                return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
        }
    }

    if ( me->calUnlocked != 0U ) {
        rearm_hidden_timeout(me);
    }
    return MODBUS_SLAVE_EX_NONE;
}

static modbus_slave_exception_t write_holding(modbus_app* me,
                                              uint16_t start,
                                              uint16_t count,
                                              uint8_t const* buffer)
{
    modbus_slave_exception_t exception;

    if ( modbus_cal_regs_overlaps(start, count) ) {
        return handle_hidden_write(me, start, count, buffer);
    }

    exception = validate_user_write(me, start, count, buffer);
    if ( exception != MODBUS_SLAVE_EX_NONE ) {
        return exception;
    }
    commit_user_write(me, start, count, buffer);
    return MODBUS_SLAVE_EX_NONE;
}

static modbus_slave_exception_t holding_registers(void* ctx,
                                                  uint16_t start,
                                                  uint16_t count,
                                                  uint8_t* buffer,
                                                  modbus_slave_register_mode_t mode)
{
    modbus_app* me = (modbus_app*)ctx;

    if ( me == NULL ) {
        return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
    }
    if ( mode == MODBUS_SLAVE_REG_READ ) {
        return read_holding(me, start, count, buffer);
    }
    return write_holding(me, start, count, buffer);
}

static modbus_slave_exception_t input_registers(void* ctx,
                                                uint16_t start,
                                                uint16_t count,
                                                uint8_t* buffer,
                                                modbus_slave_register_mode_t mode)
{
    modbus_app* me = (modbus_app*)ctx;

    if ( me == NULL || mode != MODBUS_SLAVE_REG_READ ) {
        return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
    }
    return read_input(me, start, count, buffer);
}

static modbus_slave_exception_t unsupported_bits(void* ctx,
                                                 uint16_t start,
                                                 uint16_t count,
                                                 uint8_t* buffer,
                                                 modbus_slave_register_mode_t mode)
{
    (void)ctx;
    (void)start;
    (void)count;
    (void)buffer;
    (void)mode;
    return MODBUS_SLAVE_EX_ILLEGAL_DATA_ADDRESS;
}

void modbus_app_ctor(modbus_app* const me, uint16_t faults)
{
    modbus_slave_callbacks_t callbacks;
    modbus_slave_identity_t identity;
    modbus_slave_port_event_t events;
    modbus_slave_status_t status;
    uint8_t channel;

    memset(me, 0, sizeof(*me));
    QActive_ctor(&me->super, Q_STATE_CAST(&modbus_app_initial));
    QTimeEvt_ctorX(&me->saveTimer, &me->super, MB_SAVE_TIMER_SIG, 0U);
    QTimeEvt_ctorX(&me->retryTimer, &me->super, MB_RETRY_TIMER_SIG, 0U);
    QTimeEvt_ctorX(&me->calTimer, &me->super, CAL_TIMEOUT_SIG, 0U);

    me->devFaults   = faults;
    me->calChannel  = 0xFFU;
    me->calType     = 0xFFU;

    for ( channel = 0U; channel < MODBUS_REG_CH_COUNT; ++channel ) {
        me->image.ch[channel].value  = MODBUS_IMAGE_INVALID_VALUE;
        me->image.ch[channel].status = MODBUS_IMAGE_NO_SAMPLE_STATUS;
    }
    me->image.cj_value  = 0L;
    me->image.cj_status = MODBUS_IMAGE_CJ_NO_SAMPLE_STATUS;

    calibrate_app_ctor(&me->cal, &me->super);

    memset(&callbacks, 0, sizeof(callbacks));
    callbacks.ctx               = me;
    callbacks.coils             = unsupported_bits;
    callbacks.discrete_inputs   = unsupported_bits;
    callbacks.holding_registers = holding_registers;
    callbacks.input_registers   = input_registers;
    callbacks.address           = current_address;

    memset(&identity, 0, sizeof(identity));
    identity.slave_id          = (uint8_t)param_app_get_address();
    identity.is_running        = 0U;
    identity.additional        = identity_additional;
    identity.additional_length = APP_IDENTITY_ADDITIONAL_LENGTH;

    status = modbus_slave_board_ctor(&callbacks, &identity);
    me->slave = (status == MODBUS_SLAVE_OK) ? modbus_slave_board_get() : NULL;

    if ( me->slave != NULL ) {
        memset(&events, 0, sizeof(events));
        events.ctx              = me;
        events.on_frame_received = on_frame_received;
        events.on_tx_timeout     = on_tx_timeout;
        (void)modbus_slave_set_event_port(me->slave, &events);
    } else {
        elog_error("modbus", "slave ctor failed (%d)", (int)status);
    }

    instance = me;
}

QActive* modbus_app_get(void)
{
    return (instance != NULL) ? &instance->super : NULL;
}

//$define${App::modbus_app} vvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv

//${App::modbus_app} .........................................................

//${App::modbus_app::SM} .....................................................
QState modbus_app_initial(modbus_app * const me, void const * const par) {
    //${App::modbus_app::SM::initial}
    QHSM_INIT(&me->cal.super, NULL, 0U);
    return Q_TRAN(&modbus_app_operating);
}

//${App::modbus_app::SM::operating} ..........................................
QState modbus_app_operating(modbus_app * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${App::modbus_app::SM::operating::initial}
        case Q_INIT_SIG: {
            status_ = Q_TRAN(&modbus_app_serving);
            break;
        }
        //${App::modbus_app::SM::operating::CAL_TIMEOUT}
        case CAL_TIMEOUT_SIG: {
            lock_hidden(me);
            dispatch_cal(me, &cal_exit_evt);
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::CAL_ENTER, CAL_EXIT, CAL_SELECT,~}
        case CAL_ENTER_SIG: // intentionally fall through
        case CAL_EXIT_SIG: // intentionally fall through
        case CAL_SELECT_SIG: // intentionally fall through
        case CAL_LOW_SIG: // intentionally fall through
        case CAL_HIGH_SIG: // intentionally fall through
        case CAL_COMMIT_SIG: // intentionally fall through
        case CAL_ABORT_SIG: // intentionally fall through
        case CAL_SETTLE_TIMER_SIG: // intentionally fall through
        case CAL_SAMPLE_TIMER_SIG: // intentionally fall through
        case CAL_CHANNEL_TIMER_SIG: // intentionally fall through
        case CH_CAL_READY_SIG: // intentionally fall through
        case CAL_SAVED_SIG: // intentionally fall through
        case CAL_SAVE_FAILED_SIG: {
            dispatch_cal(me, e);
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::CH_DATA}
        case CH_DATA_SIG: {
            meas_evt_t const* evt = Q_EVT_CAST(meas_evt_t);

            if ( evt->channel < MODBUS_REG_CH_COUNT ) {
                me->image.ch[evt->channel].value =
                    (evt->status != 0U) ? MODBUS_IMAGE_INVALID_VALUE : evt->value;
                me->image.ch[evt->channel].status = evt->status;
            }
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::CJ_TEMP}
        case CJ_TEMP_SIG: {
            meas_evt_t const* evt = Q_EVT_CAST(meas_evt_t);

            me->image.cj_value  = evt->value;
            me->image.cj_status = evt->status;
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::PARAM_SAVED}
        case PARAM_SAVED_SIG: {
            me->devFaults &= (uint16_t)~MODBUS_APP_DEV_FAULT_SAVE;
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::PARAM_SAVE_FAILED}
        case PARAM_SAVE_FAILED_SIG: {
            me->devFaults |= MODBUS_APP_DEV_FAULT_SAVE;
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::MB_SAVE_TIMER}
        case MB_SAVE_TIMER_SIG: {
            uint32_t now = board_tick_get();
            bool recent_frame;
            bool cap_reached;

            if ( me->saveFirstTick == 0U ) {
                me->saveFirstTick = now;
            }
            recent_frame = ((uint32_t)(now - me->lastFrameTick) < 500U) ? true
                                                                        : false;
            cap_reached  = ((uint32_t)(now - me->saveFirstTick) >= 10000U) ? true
                                                                           : false;

            if ( recent_frame && !cap_reached ) {
                (void)QTimeEvt_rearm(&me->saveTimer, 500U);
            } else if ( storage_app_get() != NULL ) {
                QACTIVE_POST(storage_app_get(), &param_save_evt, me);
                me->saveFirstTick = 0U;
            }
            status_ = Q_HANDLED();
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

//${App::modbus_app::SM::operating::serving} .................................
QState modbus_app_serving(modbus_app * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${App::modbus_app::SM::operating::serving}
        case Q_ENTRY_SIG: {
            modbus_slave_status_t start_status;

            if ( me->slave == NULL ) {
                QACTIVE_POST(&me->super, &start_failed_evt, &me->super);
            } else {
                start_status = modbus_slave_start(me->slave);
                if ( start_status != MODBUS_SLAVE_OK ) {
                    elog_error("modbus", "slave start failed (%d)",
                               (int)start_status);
                    QACTIVE_POST(&me->super, &start_failed_evt, &me->super);
                } else {
                    modbus_slave_set_running(me->slave, 1U);
                }
            }
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::serving}
        case Q_EXIT_SIG: {
            if ( me->slave != NULL ) {
                modbus_slave_stop(me->slave);
                modbus_slave_set_running(me->slave, 0U);
            }
            lock_hidden(me);
            dispatch_cal(me, &cal_exit_evt);
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::serving::MB_FRAME_RCVED}
        case MB_FRAME_RCVED_SIG: {
            me->lastFrameTick = board_tick_get();
            if ( me->slave != NULL ) {
                (void)modbus_slave_advance(me->slave);
            }
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::serving::MB_TX_TIMEOUT}
        case MB_TX_TIMEOUT_SIG: {
            ++me->txTimeouts;
            elog_warn("modbus", "tx timeout");
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::serving::MB_START_FAILED}
        case MB_START_FAILED_SIG: {
            status_ = Q_TRAN(&modbus_app_fault);
            break;
        }
        default: {
            status_ = Q_SUPER(&modbus_app_operating);
            break;
        }
    }
    return status_;
}

//${App::modbus_app::SM::operating::fault} ...................................
QState modbus_app_fault(modbus_app * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${App::modbus_app::SM::operating::fault}
        case Q_ENTRY_SIG: {
            if ( me->slave != NULL ) {
                modbus_slave_stop(me->slave);
            }
            QTimeEvt_armX(&me->retryTimer, 5000U, 0U);
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::fault}
        case Q_EXIT_SIG: {
            QTimeEvt_disarm(&me->retryTimer);
            status_ = Q_HANDLED();
            break;
        }
        //${App::modbus_app::SM::operating::fault::MB_RETRY_TIMER}
        case MB_RETRY_TIMER_SIG: {
            status_ = Q_TRAN(&modbus_app_serving);
            break;
        }
        default: {
            status_ = Q_SUPER(&modbus_app_operating);
            break;
        }
    }
    return status_;
}
//$enddef${App::modbus_app} ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

